import * as z from "zod";
import { stepNameSchema } from "../spec/step-name.js";

const uuidV4 = "[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}";
const end = "(?![\\s\\S])";

/** Generated by the filesystem boundary; never inferred from capture time or a step name. */
export const attemptIdSchema = z.string().regex(new RegExp(`^${uuidV4}${end}`), "Supply a canonical lowercase UUID v4 attempt ID.");

const identitySchema = z.strictObject({ step: stepNameSchema, attemptId: attemptIdSchema });
const filenames = { image: "image.png", raw: "raw.png", snapshot: "snapshot.json" } as const;
type ArtifactKind = keyof typeof filenames;

function artifactPathSchema(kind: ArtifactKind) {
  const filename = filenames[kind].replaceAll(".", "\\.");
  return z.string().regex(
    new RegExp(`^attempts/[a-z][a-z0-9_-]{0,63}/${uuidV4}/${filename}${end}`),
    "Use the canonical output-folder-relative path for this artifact.",
  );
}

/** Structural export. Complete validation also binds every path to this step and attempt. */
export const attemptArtifactsStructureSchema = z.strictObject({
  step: stepNameSchema,
  attemptId: attemptIdSchema,
  image: artifactPathSchema("image").optional(),
  raw: artifactPathSchema("raw").optional(),
  snapshot: artifactPathSchema("snapshot").optional(),
}).describe("Managed artifact references for one attempt. Omit unavailable files. Complete validation uses attemptArtifactsSchema to bind paths to the exact step and attempt ID.");

/** Planned destinations only. These paths do not assert that files were produced or saved. */
export function planAttemptArtifacts(input: { step: string; attemptId: string }): {
  directory: string; image: string; raw: string; snapshot: string;
} {
  return pathsFor(identitySchema.parse(input));
}

function pathsFor({ step, attemptId }: { step: string; attemptId: string }) {
  const directory = `attempts/${step}/${attemptId}`;
  return {
    directory,
    image: `${directory}/${filenames.image}`,
    raw: `${directory}/${filenames.raw}`,
    snapshot: `${directory}/${filenames.snapshot}`,
  };
}

export const attemptArtifactsSchema = attemptArtifactsStructureSchema.superRefine((attempt, context) => {
  // Zod also runs refinements after nonfatal format issues. Do not re-parse and
  // throw here: safeParse must return diagnostics for malformed identities.
  const planned = pathsFor(attempt);
  for (const kind of Object.keys(filenames) as ArtifactKind[]) {
    if (attempt[kind] !== undefined && attempt[kind] !== planned[kind]) {
      context.addIssue({ code: "custom", path: [kind], message: "The artifact must belong to this exact step and attempt ID." });
    }
  }
});

export type AttemptArtifacts = z.output<typeof attemptArtifactsSchema>;

/** Only recorded managed references. Filesystem containment and cleanup eligibility are separate gates. */
export function referencedAttemptArtifacts(input: unknown): { kind: ArtifactKind; path: string }[] {
  const attempt = attemptArtifactsSchema.parse(input);
  return (Object.keys(filenames) as ArtifactKind[]).flatMap((kind) => {
    const path = attempt[kind];
    return path === undefined ? [] : [{ kind, path }];
  });
}
